import React, { useMemo } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useSelector } from 'react-redux';

const Sidebar = ({ isMobile = false, onClose = () => {} }) => {
  const user = useSelector((state) => state.auth.user);
  const location = useLocation();
  const isAdmin = user?.role === 'admin';

  // ... остальной код menuItems такой же ...

  // Закрытие меню при клике на ссылку (для мобильных)
  const handleLinkClick = () => {
    if (isMobile && onClose) {
      onClose();
    }
  };

  return (
    <aside
      style={{
        position: isMobile ? 'fixed' : 'relative',
        left: 0,
        top: 0,
        height: '100vh',
        width: 260,
        background: 'linear-gradient(180deg, #0f172a 0%, #1e293b 50%, #0f172a 100%)',
        color: '#fff',
        display: 'flex',
        flexDirection: 'column',
        boxShadow: '4px 0 24px rgba(0,0,0,0.15)',
        zIndex: 50,
        transform: isMobile ? 'translateX(0)' : 'none',
        transition: 'transform 0.3s ease',
      }}
      aria-label="Боковое меню навигации"
    >
      {/* Логотип - добавляем onClick для мобильных */}
      <div 
        style={{ 
          padding: '24px 20px', 
          borderBottom: '1px solid rgba(255,255,255,0.08)',
          cursor: 'pointer',
        }}
        onClick={handleLinkClick}
      >
        {/* ... содержимое логотипа без изменений ... */}
      </div>

      {/* Навигация */}
      <nav style={{ flex: 1, padding: '20px 12px', overflowY: 'auto', overflowX: 'hidden' }}>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {filteredItems.map((item) => (
            <li key={item.path} style={{ marginBottom: 4 }}>
              <NavLink
                to={item.path}
                end={item.path === '/'}
                onClick={handleLinkClick}
                // ... остальные стили без изменений ...
              >
                {/* ... содержимое ... */}
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>

      {/* Профиль */}
      <div style={{ padding: '16px 12px', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
        {/* ... содержимое профиля без изменений ... */}
      </div>
    </aside>
  );
};

export default Sidebar;
